import React, { useState, useMemo } from 'react';

/**
 * CoatingParametersPanel
 *
 * Renders adjustable sliders for coating process parameters (thickness, particle size,
 * utilization, oxidant ratio) and recalculates material quantities for the SeaLion
 * oCVD PEDOT powder coating template.
 *
 * Props:
 *   project         – current project object (must have coating_parameters)
 *   onUpdateProject – callback to update project with recalculated quantities
 */
const CoatingParametersPanel = ({ project, onUpdateProject }) => {
  const cp = project?.coating_parameters;
  if (!cp || !cp.enabled) return null;

  const paramDefs = cp.params || {};
  const constants = cp.constants || {};
  const quantityMap = cp.quantity_map || [];

  // Initialize param values from project state or defaults
  const initialValues = {};
  for (const [key, def] of Object.entries(paramDefs)) {
    initialValues[key] = project?.coating_param_values?.[key] ?? def.default;
  }

  const [values, setValues] = useState(initialValues);
  const [dirty, setDirty] = useState(false);

  const handleChange = (key, val) => {
    setValues(prev => ({ ...prev, [key]: val }));
    setDirty(true);
  };

  // Compute derived quantities from current slider values
  const derived = useMemo(() => {
    const t_nm = values.coating_thickness_nm || 20;
    const d_um = values.particle_diameter_um || 10;
    const util = (values.utilization_pct || 65) / 100;
    const oxRatio = values.oxidant_molar_ratio || 2.3;

    const rho_pedot = constants.pedot_density_g_cm3 || 1.5;     // g/cm³
    const rho_particle = constants.particle_density_g_cm3 || 4.7; // g/cm³
    const mw_edot = constants.mw_edot || 142.2;
    const mw_vocl3 = constants.mw_vocl3 || 173.3;
    const throughput = constants.throughput_kg_hr || 0.1;

    // Convert units
    const t_cm = t_nm * 1e-7;           // nm → cm
    const d_cm = d_um * 1e-4;           // µm → cm
    const r_cm = d_cm / 2;

    // Surface area per gram of spherical particles: SA = 3 / (ρ × r)  [cm²/g]
    // Per kg: SA_kg = SA × 1000
    const sa_per_g = 3 / (rho_particle * r_cm);  // cm²/g

    // PEDOT mass per gram of particles: m = SA × t × ρ_PEDOT  [g/g]
    const pedot_per_g_particles = sa_per_g * t_cm * rho_pedot;

    // Per 1 kg coated output:
    // output = particles + PEDOT coating
    // let x = kg particles in 1 kg output
    // x + x * pedot_per_g_particles = 1  →  x = 1 / (1 + pedot_per_g_particles)
    const particle_fraction = 1 / (1 + pedot_per_g_particles);
    const pedot_mass_kg = 1 - particle_fraction;  // kg PEDOT per kg output

    // EDOT needed (MW_EDOT ≈ MW_PEDOT_repeat, so ~1:1 mass conversion)
    const edot_kg = pedot_mass_kg / util;

    // VOCl₃ needed: moles_EDOT × oxRatio × MW_VOCl₃
    const moles_edot = (edot_kg * 1000) / mw_edot;  // edot in grams / MW
    const vocl3_kg = (moles_edot * oxRatio * mw_vocl3) / 1000;

    // Active material kg (per 1 kg output)
    const active_material_kg = particle_fraction;

    // Reactor electricity scales with batch time: 1 kg / throughput × 0.5 kW base
    const batch_hours = 1 / throughput;
    const reactor_kwh = batch_hours * 0.5;

    // Weight % add-on
    const wt_pct = pedot_mass_kg * 100;

    return {
      active_material_kg: Math.round(active_material_kg * 10000) / 10000,
      edot_kg: Math.round(edot_kg * 10000) / 10000,
      vocl3_kg: Math.round(vocl3_kg * 10000) / 10000,
      reactor_kwh: Math.round(reactor_kwh * 100) / 100,
      pedot_wt_pct: Math.round(wt_pct * 100) / 100,
      pedot_mass_kg: Math.round(pedot_mass_kg * 10000) / 10000,
    };
  }, [values, constants]);

  // Apply: update process quantities in the project
  const handleApply = () => {
    if (!onUpdateProject || !project) return;

    const updatedProcesses = { ...project.processes };

    for (const mapping of quantityMap) {
      const proc = updatedProcesses[mapping.process_id];
      if (!proc) continue;

      const inputs = Array.isArray(proc.lci_inputs) ? [...proc.lci_inputs] : [];
      const idx = mapping.input_index;
      if (idx < inputs.length) {
        const newQty = derived[mapping.formula];
        if (newQty !== undefined) {
          inputs[idx] = { ...inputs[idx], quantity: newQty };
        }
      }
      updatedProcesses[mapping.process_id] = { ...proc, lci_inputs: inputs };
    }

    onUpdateProject({
      ...project,
      processes: updatedProcesses,
      coating_param_values: { ...values },
    });

    setDirty(false);
  };

  // Styles
  const sectionStyle = {
    background: '#f0f7ff',
    border: '1px solid #c8ddf5',
    borderRadius: '8px',
    padding: '12px 14px',
    marginBottom: '12px',
  };

  const titleStyle = {
    fontSize: '13px',
    fontWeight: 600,
    color: '#1a56a0',
    marginBottom: '2px',
  };

  const descStyle = {
    fontSize: '11px',
    color: '#666',
    marginBottom: '10px',
    fontStyle: 'italic',
  };

  const sliderRowStyle = {
    display: 'grid',
    gridTemplateColumns: '140px 1fr 60px 50px',
    alignItems: 'center',
    gap: '8px',
    marginBottom: '6px',
  };

  const labelStyle = {
    fontSize: '12px',
    color: '#444',
    fontWeight: 500,
  };

  const valueBoxStyle = {
    fontSize: '12px',
    fontFamily: 'monospace',
    color: '#1a56a0',
    fontWeight: 600,
    textAlign: 'right',
  };

  const unitStyle = {
    fontSize: '11px',
    color: '#888',
  };

  const derivedRowStyle = {
    display: 'flex',
    justifyContent: 'space-between',
    fontSize: '11px',
    color: '#555',
    padding: '2px 0',
  };

  return (
    <div style={sectionStyle}>
      <div style={titleStyle}>{cp.title || 'Coating Parameters'}</div>
      <div style={descStyle}>{cp.description}</div>

      {/* Parameter sliders */}
      {Object.entries(paramDefs).map(([key, def]) => (
        <div key={key} style={sliderRowStyle}>
          <span style={labelStyle}>{def.label}</span>
          <input
            type="range"
            min={def.min}
            max={def.max}
            step={def.step}
            value={values[key] ?? def.default}
            onChange={(e) => handleChange(key, parseFloat(e.target.value))}
            style={{ width: '100%', cursor: 'pointer' }}
          />
          <span style={valueBoxStyle}>{values[key] ?? def.default}</span>
          <span style={unitStyle}>{def.unit}</span>
        </div>
      ))}

      {/* Derived quantities preview */}
      <div style={{
        background: '#fff', borderRadius: '6px', padding: '8px 10px',
        marginTop: '8px', border: '1px solid #e0e8f0',
      }}>
        <div style={{ fontSize: '11px', fontWeight: 600, color: '#666', marginBottom: '4px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
          Calculated Quantities (per kg output)
        </div>
        <div style={derivedRowStyle}>
          <span>PEDOT add-on</span>
          <span style={{ fontFamily: 'monospace', fontWeight: 600 }}>{derived.pedot_wt_pct} wt%</span>
        </div>
        <div style={derivedRowStyle}>
          <span>Active Material</span>
          <span style={{ fontFamily: 'monospace' }}>{derived.active_material_kg} kg</span>
        </div>
        <div style={derivedRowStyle}>
          <span>EDOT monomer</span>
          <span style={{ fontFamily: 'monospace' }}>{derived.edot_kg} kg</span>
        </div>
        <div style={derivedRowStyle}>
          <span>VOCl₃ oxidant</span>
          <span style={{ fontFamily: 'monospace' }}>{derived.vocl3_kg} kg</span>
        </div>
        <div style={derivedRowStyle}>
          <span>Reactor electricity</span>
          <span style={{ fontFamily: 'monospace' }}>{derived.reactor_kwh} kWh</span>
        </div>
      </div>

      {/* Apply button */}
      <div style={{ marginTop: '10px', display: 'flex', justifyContent: 'center', gap: '8px' }}>
        <button
          onClick={handleApply}
          style={{
            padding: '6px 20px',
            fontSize: '12px',
            fontWeight: 600,
            background: dirty ? '#1a73e8' : '#a0c4f1',
            color: '#fff',
            border: 'none',
            borderRadius: '4px',
            cursor: dirty ? 'pointer' : 'default',
            transition: 'background 0.2s',
          }}
        >
          {dirty ? 'Apply & Update Quantities' : 'Quantities Up to Date'}
        </button>
      </div>
    </div>
  );
};

export default CoatingParametersPanel;
